INSERT INTO video_standard_baselines VALUES ('narrated-software-demo-20261109','446042327ce9bb0c8a0f163f4658df8fbc4dc60637a6fdbfba14085599a2d88f','MAC-MELBOURNE-AI-BUSINESS','Phill McGurk','2026-11-09','This actually makes sense now.. Well done..Lets now lock this in as the new starting standards and we can then improve, enhance, and make client changes from this moment on..','/Volumes/Mini Mini 2T Storage/tmp/uni-2934-cinematic/keyboard-tips-review/AI-in-Business-Keyboard-Tips.mp4','266.4','25','OWNER_APPROVED_BASELINE','HOLD') ON CONFLICT(baseline_id) DO NOTHING;
INSERT INTO video_standard_requirements VALUES ('narrated-software-demo-20261109','1','One frame timeline for original whole-sentence narration, actual clean screen actions, captions and reading windows') ON CONFLICT(baseline_id,ordinal) DO NOTHING;
INSERT INTO video_standard_requirements VALUES ('narrated-software-demo-20261109','2','Large readable prompt and response; complete workflow: Open, Brief, Send, Check, Correct, Approve') ON CONFLICT(baseline_id,ordinal) DO NOTHING;
INSERT INTO video_standard_requirements VALUES ('narrated-software-demo-20261109','3','No premature send: spoken Do not send yet plus actual Shift+Enter new-line action and visible tip; describe visual-only tips honestly') ON CONFLICT(baseline_id,ordinal) DO NOTHING;
INSERT INTO video_standard_requirements VALUES ('narrated-software-demo-20261109','4','Preserve native source cadence; no borrowed-word edits; no time-stretched speech; qualified continuous typing capture') ON CONFLICT(baseline_id,ordinal) DO NOTHING;
INSERT INTO video_standard_requirements VALUES ('narrated-software-demo-20261109','5','Anchor instructions to corresponding clicks within250ms; active typing unexplained unchanged text <=750ms') ON CONFLICT(baseline_id,ordinal) DO NOTHING;
INSERT INTO video_standard_requirements VALUES ('narrated-software-demo-20261109','6','Explicit reading intervals >=3s and >=words/3 seconds, with gentle motion/progress rather than apparent stalls') ON CONFLICT(baseline_id,ordinal) DO NOTHING;
INSERT INTO video_standard_requirements VALUES ('narrated-software-demo-20261109','7','Final exact-SHA playback at1x unmuted; separate fullscreen from replay; no restart when entering fullscreen') ON CONFLICT(baseline_id,ordinal) DO NOTHING;
INSERT INTO video_standard_requirements VALUES ('narrated-software-demo-20261109','8','Fictional generic business content only; every-second privacy frame review plus transcript/OCR checks') ON CONFLICT(baseline_id,ordinal) DO NOTHING;
INSERT INTO video_standard_requirements VALUES ('narrated-software-demo-20261109','9','Preserve approved master; client changes produce new artifacts with parent SHA and fresh affected-action and full-playback checks') ON CONFLICT(baseline_id,ordinal) DO NOTHING;
INSERT INTO video_standard_requirements VALUES ('narrated-software-demo-20261109','10','Retain independent watch/listen, six-board, rights, spending and release gates; owner baseline approval does not imply they ran') ON CONFLICT(baseline_id,ordinal) DO NOTHING;
